import ascon

key = bytes.fromhex("bf473b6dd5d29bc4d9b4e2d4483c0716")
nonce = bytes.fromhex("00040000000000010000000000000000")
pt = bytes.fromhex("")
aad = b""

ct_full = ascon.encrypt(key, nonce, aad, pt, variant="Ascon-128")
cipher = ct_full[:-16]
tag = ct_full[-16:]

print("Python Ciphertext (hex):", cipher.hex())
print("Python Tag (hex):", tag.hex())
